instrument RTP_DIF {
    // Instrument parameters
    parameter double lambda = 2.36;
    parameter double DM = 3.355;
    parameter double Mono_tilt = 0;
    parameter string powder = "Na2Ca3Al2F14.laz";
    parameter double det_rotation = 45;

    // Derived quantities
    double takeoff_angle = 2 * asin(lambda / 2 / DM) * 180 / 3.141592653589793;
    printf("RTP_DIF: Monochromator take-off angle=%g [deg]\n", takeoff_angle);

    // Components
    Progress_bar Origin(AT(0, 0, 0), RELATIVE_ABSOLUTE, ROTATED(0, 0, 0), RELATIVE_ABSOLUTE);

    Source_gen source(
        AT(0, 0, 0), RELATIVE Origin,
        ROTATED(0, 0, 0), RELATIVE_ABSOLUTE,
        radius = 0.154 / 2,
        dist = 1.16 + 1.50,
        focus_xw = 0.11,
        focus_yh = 0.03,
        lambda0 = lambda,
        dlambda = 0.2,
        I1 = 2.79e12 / 4 / 3.141592653589793,
        T1 = 300
    );

    Guide CoarseCollimator1(
        AT(0, 0, 0.01), RELATIVE source,
        ROTATED(0, 0, 0), RELATIVE_ABSOLUTE,
        w1 = 0.154,
        h1 = 0.154,
        l = 1.16125,
        m = 0
    );

    Guide CoarseCollimator2(
        AT(0, 0, 1.16125 + 0.003), RELATIVE CoarseCollimator1,
        ROTATED(0, 0, 0), RELATIVE_ABSOLUTE,
        w1 = 0.11,
        h1 = 0.11,
        l = 1.5,
        m = 0
    );

    Monitor_nD lmon(
        AT(0, 0, 1.5 + 0.01), RELATIVE CoarseCollimator2,
        ROTATED(0, 0, 0), RELATIVE_ABSOLUTE,
        xwidth = 0.11,
        bins = 50,
        options = "slit disk, auto wavelength"
    );

    Arm Be_Position(
        AT(0, 0, 0.147 + 0.15 / 2), RELATIVE lmon,
        ROTATED(0, 0, 0), RELATIVE_ABSOLUTE
    );

    Arm mono_cradle(
        AT(0, 0, 0.145 + 0.15 / 2 + 0.176), RELATIVE Be_Position,
        ROTATED(0, 0, 0), RELATIVE_ABSOLUTE,
        SPLIT(10)
    );

    Arm mono_rotation(
        AT(0, 0, 0), RELATIVE mono_cradle,
        ROTATED(0, -asin(lambda / 2 / DM) * 180 / 3.141592653589793, 0), RELATIVE mono_cradle
    );

    Monochromator_curved mono1(
        AT(-0.01, 0, 0), RELATIVE mono_rotation,
        ROTATED(0, Mono_tilt, 0), RELATIVE mono_rotation,
        reflect = "HOPG.rfl",
        transmit = "HOPG.trm",
        NH = 1,
        NV = 1,
        mosaich = 48,
        mosaicv = 48,
        RV = 0,
        RH = 0,
        DM = DM,
        width = 0.11,
        height = 0.03
    );
    EXTEND mono1 {
        int mono_index = 0;
        if (SCATTERED) mono_index = 1;
    }

    Monochromator_curved mono2(
        AT(0, 0, 0), RELATIVE mono_rotation,
        ROTATED(0, 0, 0), RELATIVE mono_rotation,
        reflect = "HOPG.rfl",
        transmit = "HOPG.trm",
        NH = 1,
        NV = 1,
        mosaich = 48,
        mosaicv = 48,
        RV = 0,
        RH = 0,
        DM = DM,
        width = 0.11,
        height = 0.03
    );
    EXTEND mono2 {
        int mono_index = 0;
        if (SCATTERED) mono_index = 2;
    }

    Monochromator_curved mono3(
        AT(0.01, 0, 0), RELATIVE mono_rotation,
        ROTATED(0, -Mono_tilt, 0), RELATIVE mono_rotation,
        reflect = "HOPG.rfl",
        transmit = "HOPG.trm",
        NH = 1,
        NV = 1,
        mosaich = 48,
        mosaicv = 48,
        RV = 0,
        RH = 0,
        DM = DM,
        width = 0.11,
        height = 0.03
    );
    EXTEND mono3 {
        int mono_index = 0;
        if (SCATTERED) mono_index = 3;
    }

    Arm mono_takeoff(
        AT(0, 0, 0), RELATIVE mono_cradle,
        ROTATED(0, -2 * asin(lambda / 2 / DM) * 180 / 3.141592653589793, 0), RELATIVE mono_cradle
    );

    Monitor_nD psd_transmit(
        AT(0, 0, 0.25), RELATIVE mono_cradle,
        ROTATED(0, 0, 0), RELATIVE_ABSOLUTE,
        xwidth = 0.12,
        yheight = 0.12,
        bins = 50,
        options = "x y"
    );
    GROUP psd_transmit mono_rt;

    Monitor_nD psd_reflect(
        AT(0, 0, 0.574), RELATIVE mono_takeoff,
        ROTATED(0, 0, 0), RELATIVE_ABSOLUTE,
        xwidth = 0.12,
        yheight = 0.12,
        bins = 50,
        options = "x y"
    );
    GROUP psd_reflect mono_rt;

    Monitor_nD sample_psd(
        AT(0, 0, 0.574 + 0.50), RELATIVE mono_takeoff,
        ROTATED(0, 0, 0), RELATIVE_ABSOLUTE,
        xwidth = 0.02,
        yheight = 0.02,
        bins = 50,
        options = "disk slit, x y"
    );

    Arm sample_position(
        AT(0, 0, 0.575 + 0.5 + 0.01), RELATIVE mono_takeoff,
        ROTATED(0, 0, 0), RELATIVE_ABSOLUTE,
        SPLIT(100)
    );

    PowderN container_in(
        AT(0, 0, 0), RELATIVE sample_position,
        ROTATED(0, 0, 0), RELATIVE_ABSOLUTE,
        reflections = "V.lau",
        radius = 0.01 / 2,
        yheight = 0.04,
        thickness = -50e-6,
        p_transmit = 0.95,
        d_phi = 50,
        concentric = 1
    );

    PowderN sample(
        AT(0, 0, 0), RELATIVE sample_position,
        ROTATED(0, 0, 0), RELATIVE_ABSOLUTE,
        reflections = powder,
        radius = 0.01 / 2,
        yheight = 0.04,
        d_phi = atan2(0.5, 1) * 180 / 3.141592653589793
    );
    EXTEND sample {
        if (!SCATTERED) ABSORB;
    }

    PowderN container_out(
        AT(0, 0, 0), RELATIVE sample_position,
        ROTATED(0, 0, 0), RELATIVE_ABSOLUTE,
        reflections = "V.lau",
        radius = 0.01 / 2,
        yheight = 0.04,
        thickness = -50e-6,
        p_transmit = 0.95,
        d_phi = 50,
        concentric = 1
    );

    Arm sample_out(
        AT(0, 0, 1), RELATIVE sample_position,
        ROTATED(0, det_rotation, 0), RELATIVE sample_position
    );

    Monitor_nD det_big(
        AT(0, 0, 0), RELATIVE sample_position,
        ROTATED(0, 0, 0), RELATIVE_ABSOLUTE,
        yheight = 0.5,
        radius = 1,
        options = "banana theta limits=[-150 150] bins=300, y bins=64"
    );

    Monitor_nD det(
        AT(0, 0, 1), RELATIVE sample_out,
        ROTATED(0, 0, 0), RELATIVE_ABSOLUTE,
        xwidth = 0.5,
        yheight = 0.0254,
        bins = 25,
        options = "x"
    );

    Shape reactor(
        AT(0, 0, -0.35), RELATIVE Origin,
        ROTATED(0, 0, 0), RELATIVE_ABSOLUTE,
        radius = 0.7 / 2,
        yheight = 0.4
    );

    // Connect components
    source -> CoarseCollimator1 -> CoarseCollimator2 -> lmon -> Be_Position -> mono_cradle -> mono_rotation -> mono1 -> mono2 -> mono3 -> mono_takeoff -> psd_transmit -> psd_reflect -> sample_psd -> sample_position -> container_in -> sample -> container_out -> sample_out -> det_big -> det -> reactor;

    // Set simulation parameters
    SET_DEFINE("seed", 123456);
    SET_DEFINE("ncount", 1e6);
    SET_DEFINE("gravity", true);
}
